import { test, expect } from '@playwright/test';

test.describe('Search Results Filtering by Category', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should filter search results by selected categories using checkboxes', async ({ page }) => {
    // Verify initial search results are displayed
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify all categories are displayed initially
    const categoryCheckboxes = page.getByRole('checkbox', { name: /category/i });
    const categoryCount = await categoryCheckboxes.count();
    expect(categoryCount).toBeGreaterThan(0);

    // Verify search results are visible
    const resultItems = page.getByRole('listitem');
    await expect(resultItems).toHaveCount(10);

    // Select multiple categories using checkboxes
    const sportsCheckbox = page.getByRole('checkbox', { name: /sports/i });
    await sportsCheckbox.click();

    const technologyCheckbox = page.getByRole('checkbox', { name: /technology/i });
    await technologyCheckbox.click();

    const fashionCheckbox = page.getByRole('checkbox', { name: /fashion/i });
    await fashionCheckbox.click();

    // Verify categories are now selected
    await expect(sportsCheckbox).toBeChecked();
    await expect(technologyCheckbox).toBeChecked();
    await expect(fashionCheckbox).toBeChecked();

    // Verify search results are filtered
    const filteredResults = page.getByRole('listitem');
    await expect(filteredResults).toHaveCount(3);

    // Verify only items from selected categories are displayed
    const sportsResult = page.getByText(/sports/i);
    await expect(sportsResult).toBeVisible();

    const technologyResult = page.getByText(/technology/i);
    await expect(technologyResult).toBeVisible();

    const fashionResult = page.getByText(/fashion/i);
    await expect(fashionResult).toBeVisible();

    // Verify other categories are not displayed
    const foodResult = page.getByText(/food/i);
    await expect(foodResult).not.toBeVisible();

    const travelResult = page.getByText(/travel/i);
    await expect(travelResult).not.toBeVisible();

    // Verify search results are sorted alphabetically
    const firstResult = page.getByText(/apple/i);
    await expect(firstResult).toBeVisible();

    const secondResult = page.getByText(/banana/i);
    await expect(secondResult).toBeVisible();

    const thirdResult = page.getByText(/orange/i);
    await expect(thirdResult).toBeVisible();

    // Verify category filter is applied
    const categoryFilter = page.getByRole('heading', { name: /filter by category/i });
    await expect(categoryFilter).toBeVisible();

    // Verify filter button is enabled
    const filterButton = page.getByRole('button', { name: /apply filter/i });
    await expect(filterButton).toBeEnabled();
  });

